// Only the E-mail-sourced cases count toward "Cases Logged (Email)" --
// Call-sourced ones are a different metric this chart doesn't need.
return items
  .filter(item => (item.json.sourcesofcomplaint || '') === 'E-mail')
  .map(item => ({ json: { date: item.json.date, agent: item.json.agent, CaseLogged: item.json.CaseLogged, dataType: 'caselogged' } }));

// Same short-code -> full-name normalization the original MTD email-report
// workflow applies post-merge, so agent names here match what
// combined_summary already uses (e.g. "Prince" -> "Prince Kumar Singh").
const NAME_MAP = { 'Prince': 'Prince Kumar Singh', 'Sachin': 'Sachin Yadav' };
const CASE_MAP = { 'yakoob': 'Yakoob' };

return items.map(item => {
  let agent = item.json.agent || '';
  if (NAME_MAP[agent]) agent = NAME_MAP[agent];
  const lower = agent.toLowerCase();
  if (CASE_MAP[lower]) agent = CASE_MAP[lower];
  return { json: { ...item.json, agent } };
});

const counts = {};

items.forEach(item => {
  const { date, agent } = item.json;
  const key = `${date}__${agent}`;

  if (!counts[key]) {
    counts[key] = { date, agent, CaseLogged: 0, Resolved: 0, Reassigned: 0, CaseUpdate: 0 };
  }

  if (item.json.dataType === 'caselogged') counts[key].CaseLogged += item.json.CaseLogged || 0;
  if (item.json.dataType === 'casesclosed') counts[key].Resolved += item.json.CasesClosed || 0;
  if (item.json.dataType === 'reassigned') counts[key].Reassigned += item.json.Reassigned || 0;
  if (item.json.dataType === 'caseupdate') counts[key].CaseUpdate += item.json.CaseUpdate || 0;
});

return Object.values(counts)
  .filter(row => row.date && row.agent)
  .map(row => ({
    json: {
      date: row.date,
      agent: row.agent,
      caseLoggedEmail: row.CaseLogged,
      resolved: row.Resolved,
      reassigned: row.Reassigned,
      caseUpdate: row.CaseUpdate
    }
  }))
  .sort((a, b) => a.json.date.localeCompare(b.json.date) || a.json.agent.localeCompare(b.json.agent));
